四、Arduino程式碼 
#include <Servo.h> 
Servo servoright; 
Servo servoleft; 

int irsenserleft=10; 
int irsensermiddle=9; 
int irsenserright=8; 
void setup() { 
servoright.attach(12); 
servoleft.attach(13); 

pinMode(irsenserleft,INPUT); 
pinMode(irsensermiddle,INPUT); 
pinMode(irsenserright,INPUT); 
} 

void loop() { 
int left=digitalRead(senL); 
int middle=digitalRead(senM); 
int right=digitalRead(senR); 
if(middle==0){ 
 servoright.writeMicroseconds(1300); 
 servoleft.writeMicroseconds(1700); 
 delay(10); 
} 
if((left==0)&&(middle==1)){ 
 servoright.writeMicroseconds(1300); 
 servoleft.writeMicroseconds(1300); 
 delay(450); 
} 
if((right==0)&&(middle==1)){ 
 servoright.writeMicroseconds(1700); 
 servoleft.writeMicroseconds(1700); 
 delay(450); 
} 
} 


